  'warehouse.robert_title': { fr: 'ROBERT, AGENT IMMOBILIER', en: 'ROBERT, REAL ESTATE AGENT', es: 'ROBERT, AGENTE INMOBILIARIO', de: "ROBERT, IMMOBILIENMAKLER" , it: "ROBERT, AGENTE IMMOBILIARE", ru: "РОБЕР, АГЕНТ ПО НЕДВИЖИМОСТИ", zh: "罗贝尔, 房地产经纪人"},
  'warehouse.robert_intro': { fr: "Robert vous présente l'entrepôt. Il a bossé pour les pros du froid pendant 20 ans, il sait ce qu'il vous faut.", en: 'Robert walks you through the warehouse. He worked with cold-chain pros for 20 years, he knows what you need.', es: 'Robert le enseña la nave. Trabajó con profesionales del frío durante 20 años, sabe lo que necesita.', de: "Robert führt Sie durch das Lager. Er hat 20 Jahre mit Kühlketten-Profis gearbeitet, er weiß, was Sie brauchen." , it: "Robert le mostra il magazzino. Ha lavorato 20 anni con professionisti della catena del freddo, sa di cosa ha bisogno.", ru: "Робер проводит вас по складу. Он 20 лет работал с профессионалами холодовой цепи, он знает, что вам нужно.", zh: "罗贝尔带您参观仓库。他与冷链专业人士共事20年，知道您需要什么。"},
  'warehouse.robert_quote': { fr: "Vous signez ici, et dans deux semaines vous embauchez votre premier chauffeur. Garanti, j'en ai vu passer des dizaines comme vous.", en: 'You sign here, and in two weeks you hire your first driver. Guaranteed, I\'ve seen dozens like you.', es: 'Firma aquí, y en dos semanas contrata a su primer chófer. Garantizado, he visto a docenas como usted.', de: "Sie unterschreiben hier, und in zwei Wochen stellen Sie Ihren ersten Fahrer ein. Garantiert, ich habe Dutzende wie Sie gesehen." , it: "", ru: "", zh: ""},
