  'mission.intro': { fr: "Pour passer à l'étape suivante, la marque doit franchir 5 paliers stratégiques. Tu peux y aller dans n'importe quel ordre.", en: "To reach the next stage, the brand must clear 5 strategic milestones. You can tackle them in any order.", es: "Para alcanzar la siguiente etapa, la marca debe superar 5 hitos estratégicos. Puedes abordarlos en cualquier orden.", de: "Um die nächste Stufe zu erreichen, muss die Marke 5 strategische Meilensteine schaffen. Reihenfolge frei wählbar." , it: "Per raggiungere la fase successiva, il marchio deve superare 5 traguardi strategici. Puoi affrontarli in qualsiasi ordine.", ru: "Чтобы перейти на следующий этап, бренд должен преодолеть 5 стратегических рубежей. Можно решать их в любом порядке.", zh: "要进入下一阶段，品牌必须达成5个战略里程碑。你可以按任意顺序攻克。"},
  'mission.visibility': { fr: 'VISIBILITÉ', en: 'VISIBILITY', es: 'VISIBILIDAD', de: "SICHTBARKEIT" , it: "VISIBILITÀ", ru: "ВИДИМОСТЬ", zh: "曝光度"},
  'mission.visibility_short': { fr: 'Visibilité', en: 'Visibility', es: 'Visibilidad', de: "Sichtbarkeit" , it: "Visibilità", ru: "Видимость", zh: "曝光度"},
  'mission.visibility_desc': { fr: 'Atteindre 60 de notoriété, la marque est désormais connue.', en: 'Reach 60 awareness, the brand is now recognized.', es: 'Alcanzar 60 de notoriedad, la marca ya es reconocida.', de: "Erreiche 60 Bekanntheit, die Marke wird jetzt erkannt." , it: "Raggiungi 60 di notorietà, ora il marchio è riconosciuto.", ru: "Достичь 60 известности, бренд теперь узнаваем.", zh: "达到60知名度,,品牌现已被认可。"},
  'mission.trust': { fr: 'CONFIANCE', en: 'TRUST', es: 'CONFIANZA', de: "VERTRAUEN" , it: "FIDUCIA", ru: "ДОВЕРИЕ", zh: "信任"},
  'mission.trust_short': { fr: 'Confiance', en: 'Trust', es: 'Confianza', de: "Vertrauen" , it: "Fiducia", ru: "Доверие", zh: "信任"},
  'mission.trust_desc': { fr: 'Atteindre 70 de réputation, la marque est respectée.', en: 'Reach 70 reputation, the brand is respected.', es: 'Alcanzar 70 de reputación, la marca es respetada.', de: "Erreiche 70 Ruf, die Marke wird respektiert." , it: "Raggiungi 70 di reputazione, il marchio è rispettato.", ru: "Достичь 70 репутации, бренд уважают.", zh: "达到70声誉,,品牌受到尊重。"},
  'mission.distribution': { fr: 'DISTRIBUTION', en: 'DISTRIBUTION', es: 'DISTRIBUCION', de: "VERTRIEB" , it: "DISTRIBUZIONE", ru: "ДИСТРИБУЦИЯ", zh: "分销"},
  'mission.distribution_short': { fr: 'Distribution', en: 'Distribution', es: 'Distribución', de: "Vertrieb" , it: "Distribuzione", ru: "Дистрибуция", zh: "分销"},
  'mission.distribution_desc': { fr: 'Signer 4 retailers (sur 6), couverture nationale prouvée.', en: 'Sign 4 retailers (out of 6), national coverage proven.', es: 'Firmar 4 retailers (de 6), cobertura nacional probada.', de: "Unterschreibe 4 Händler (von 6), nationale Abdeckung bewiesen." , it: "Firma 4 retailer (su 6), copertura nazionale dimostrata.", ru: "Подписать 4 ритейлера (из 6), национальное покрытие доказано.", zh: "签下4家零售商（共6家）,,证明全国覆盖。"},
  'mission.competition': { fr: 'CONCURRENCE', en: 'COMPETITION', es: 'COMPETENCIA', de: "WETTBEWERB" , it: "CONCORRENZA", ru: "КОНКУРЕНЦИЯ", zh: "竞争"},
  'mission.competition_short': { fr: 'Concurrence', en: 'Competition', es: 'Competencia', de: "Wettbewerb" , it: "Concorrenza", ru: "Конкуренция", zh: "竞争"},
  'mission.competition_desc': { fr: 'Dépasser TOUS les concurrents en parts de marché, devenir le n°1.', en: 'Beat ALL competitors in market share, become the n°1.', es: 'Superar a TODOS los competidores en cuota de mercado, ser el n°1.', de: "Schlage ALLE Konkurrenten im Marktanteil, werde die Nr. 1." , it: "Batti TUTTI i concorrenti per quota di mercato, diventa il n°1.", ru: "Обойти ВСЕХ конкурентов по доле рынка, стать №1.", zh: "在市场份额上击败所有竞争对手,,成为第一。"},
  'mission.perennity': { fr: 'PÉRENNITÉ', en: 'PERENNITY', es: 'PERENNIDAD', de: "BESTÄNDIGKEIT" , it: "SOLIDITÀ", ru: "УСТОЙЧИВОСТЬ", zh: "可持续"},
  'mission.perennity_short': { fr: 'Pérennité', en: 'Perennity', es: 'Perennidad', de: "Beständigkeit" , it: "Solidità", ru: "Устойчивость", zh: "可持续"},
  'mission.perennity_desc': { fr: 'Tenir 15 mois en Phase 3, preuve que ce n\'est pas un coup de chance.', en: 'Hold 15 months in Phase 3, proof it\'s not luck.', es: 'Aguantar 15 meses en Fase 3, prueba de que no es suerte.', de: "Halte 15 Monate in Phase 3, Beweis, dass es kein Glück war." , it: "", ru: "", zh: ""},
  'mission.phase4_unlocked_pending': { fr: "Toutes les missions accomplies. Continue à faire grandir ta marque.", en: "All missions completed. Keep growing your brand.", es: "Todas las misiones completadas. Sigue haciendo crecer tu marca.", de: "Alle Missionen erfüllt. Bau deine Marke weiter aus." , it: "Tutte le missioni completate. Continua a far crescere il tuo marchio.", ru: "Все миссии выполнены. Продолжайте развивать бренд.", zh: "所有任务已完成。继续发展你的品牌。"},

